// Filter customers who haven't ordered in 30+ days
const customers = [];
const now = new Date();
const thirtyDaysAgo = new Date(now.getTime() - (30 * 24 * 60 * 60 * 1000));

// Group by customer
$itemAll().forEach(item => {
  const customerId = item.json.customer_id;
  const lastOrderDate = new Date(item.json.last_order_date);

  if (lastOrderDate < thirtyDaysAgo) {
    // Find customer details
    const customerDetails = $node["Find Active Customers"].json.find(c => c.id === customerId);
    if (customerDetails) {
      customers.push({
        ...customerDetails,
        last_order_date: item.json.last_order_date,
        total_orders: item.json.total_orders,
        avg_order_value: item.json.avg_order_value,
        lifetime_value: item.json.lifetime_value,
        days_since_last_order: Math.floor((now - lastOrderDate) / (1000 * 60 * 60 * 24))
      });
    }
  }
});

// Remove duplicates
const uniqueCustomers = customers.filter((customer, index, self) => 
  index === self.findIndex(c => c.id === customer.id)
);

return uniqueCustomers;

// Segment customers based on their profile
const customer = $json;

// Calculate recency score (days since last order)
const recencyScore = Math.min(customer.days_since_last_order / 180, 1); // Max 180 days = score 1

// Calculate frequency score (total orders)
const frequencyScore = Math.min(customer.total_orders / 20, 1); // Max 20 orders = score 1

// Calculate monetary score (lifetime value)
const monetaryScore = Math.min(customer.lifetime_value / 5000, 1); // Max R$5000 = score 1

// Calculate RFM score
const rfmScore = (recencyScore * 0.3 + frequencyScore * 0.3 + monetaryScore * 0.4);

// Determine segment and offer
let segment = 'bronze';
let discountPercent = 10;
let campaignType = 'gentle_reactivation';
let emailTemplate = 'dormant_light';

if (rfmScore >= 0.7) {
  segment = 'gold';
  discountPercent = 20;
  campaignType = 'vip_reactivation';
  emailTemplate = 'dormant_vip';
} else if (rfmScore >= 0.4) {
  segment = 'silver';
  discountPercent = 15;
  campaignType = 'standard_reactivation';
  emailTemplate = 'dormant_standard';
}

// Generate reactivation coupon
const couponCode = `VOLTA${customer.id}`;
const validDays = segment === 'gold' ? 14 : 7;

// Personalized messaging based on last order
const lastOrderDays = customer.days_since_last_order;
let urgencyMessage = 'Faz tempo que não vemos você!';
if (lastOrderDays > 90) {
  urgencyMessage = 'Sentimos sua falta! Já fazem 3 meses...';
} else if (lastOrderDays > 60) {
  urgencyMessage = 'Faz tempo que você não aparece!';
}

return {
  ...customer,
  segment: segment.toUpperCase(),
  discountPercent,
  couponCode,
  validDays,
  campaignType,
  emailTemplate,
  urgencyMessage,
  rfmScore: rfmScore.toFixed(3),
  personalization: {
    favoriteCategory: 'Eletrônicos', // Would be calculated from order history
    lastProducts: ['iPhone 15', 'MacBook Pro'], // Would be from last order
    avgOrderValue: customer.avg_order_value
  }
};

// Generate personalized reactivation email
const data = $node["Segment Customer"].json;
const customer = data;
const couponCode = data.couponCode;
const discountPercent = data.discountPercent;
const validDays = data.validDays;
const urgencyMessage = data.urgencyMessage;

// Coupon URL
const couponUrl = `https://getnexo.com.br?coupon=${couponCode}&reactivation=true&ref=${customer.id}`;

// Personalized product recommendations
const recommendations = [
  'Seus produtos favoritos com desconto',
  'Novidades que você pode gostar',
  'Ofertas especiais para você'
];

// Email content based on template
templates = {
  'dormant_vip': {
    subject: `Oi ${customer.name}! Sentimos sua falta... 🎁 20% OFF Especial`,
    greeting: `Olá ${customer.name}, nosso cliente VIP!`,
    body: `${urgencyMessage} 😔\n\nVocê fez ${customer.total_orders} pedidos conosco totalizando R$ ${customer.lifetime_value.toFixed(2)}. Como você é especial para nós, criamos uma oferta VIP:`,
    discount: `20% OFF em TODA loja`,
    benefits: ['Entrega gratuita', 'Suporte prioritário', 'Cupom extra de R$50']
  },
  'dormant_standard': {
    subject: `Oi ${customer.name}! Temos saudades suas! 🛍️ 15% OFF`,
    greeting: `Olá ${customer.name}!`,
    body: `${urgencyMessage}\n\nVocê é um cliente valioso para nós com ${customer.total_orders} pedidos. Para te receber de volta:`,
    discount: `15% OFF em TODA loja`,
    benefits: ['Frete grátis acima de R$200', 'Cupom de boas-vindas']
  },
  'dormant_light': {
    subject: `Oi ${customer.name}! Passamos para dizer oi! 👋 10% OFF`,
    greeting: `Olá ${customer.name}!`,
    body: `${urgencyMessage}\n\nGostaríamos de te ver novamente na nossa loja. Que tal esta oferta especial:`,
    discount: `10% OFF para você voltar`,
    benefits: ['Frete grátis', 'Atendimento personalizado']
  }
};

const template = templates[data.emailTemplate];

// Generate HTML email
const emailHtml = `
<!DOCTYPE html>
<html lang="pt-BR">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>${template.subject}</title>
  <style>
    body { font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif; line-height: 1.6; color: #333; background: #f8f9fa; }
    .container { max-width: 600px; margin: 20px auto; background: white; border-radius: 12px; overflow: hidden; box-shadow: 0 10px 30px rgba(0,0,0,0.1); }
    .header { background: linear-gradient(135deg, #667eea 0%, #764ba2 100%); color: white; padding: 40px 30px; text-align: center; }
    .content { padding: 30px; }
    .coupon { background: linear-gradient(135deg, #f093fb 0%, #f5576c 100%); color: white; padding: 30px; border-radius: 15px; text-align: center; margin: 25px 0; }
    .coupon-code { font-size: 24px; font-weight: bold; letter-spacing: 2px; margin: 15px 0; font-family: monospace; }
    .cta-button { display: inline-block; background: #28a745; color: white; padding: 15px 35px; text-decoration: none; border-radius: 25px; font-weight: bold; margin: 20px 0; box-shadow: 0 4px 15px rgba(40, 167, 69, 0.3); }
    .benefits { background: #f8f9fa; padding: 20px; border-radius: 8px; margin: 20px 0; }
    .benefits ul { margin: 0; padding-left: 20px; }
    .benefits li { margin: 5px 0; }
    .footer { background: #343a40; color: white; padding: 20px; text-align: center; font-size: 12px; }
    .stats { background: #e9ecef; padding: 15px; border-radius: 8px; margin: 20px 0; text-align: center; }
  </style>
</head>
<body>
  <div class="container">
    <div class="header">
      <h1>💙 ${customer.name}</h1>
      <p>Sentimos sua falta na GetNexo!</p>
    </div>

    <div class="content">
      <p>${template.greeting}</p>

      <p>${template.body}</p>

      <div class="stats">
        <p><strong>Seus ${customer.total_orders} pedidos conosco totalizam R$ ${customer.lifetime_value.toFixed(2)}</strong></p>
        <p>Última visita: ${customer.days_since_last_order} dias atrás</p>
      </div>

      <div class="coupon">
        <div class="discount">🎁 ${template.discount}</div>
        <div class="coupon-code">${couponCode}</div>
        <div>⏰ Válido por ${validDays} dias</div>
      </div>

      <div style="text-align: center;">
        <a href="${couponUrl}" class="cta-button">Usar Meu Desconto Agora</a>
      </div>

      <div class="benefits">
        <h3>Além do desconto, você também ganha:</h3>
        <ul>
          ${template.benefits.map(benefit => `<li>${benefit}</li>`).join('')}
        </ul>
      </div>

      <p><strong>Algumas sugestões especiais para você:</strong></p>
      <ul>
        ${recommendations.map(rec => `<li>${rec}</li>`).join('')}
      </ul>

      <p>Esperamos te ver em breve! 🛍️✨</p>

      <p>Abraços,<br>
      <strong>Equipe GetNexo</strong></p>
    </div>

    <div class="footer">
      <p>Não quer mais receber nossas ofertas? <a href="https://getnexo.com.br/unsubscribe?email=${customer.email}" style="color: #ffc107;">Cancelar inscrição</a></p>
      <p>GetNexo - Sua loja favorita online</p>
    </div>
  </div>
</body>
</html>`;

const emailText = `${template.subject}

${template.greeting}

${template.body}

Seus ${customer.total_orders} pedidos conosco totalizam R$ ${customer.lifetime_value.toFixed(2)}
Última visita: ${customer.days_since_last_order} dias atrás

🎁 ${template.discount}
Código: ${couponCode}
Válido por: ${validDays} dias

Use agora: ${couponUrl}

Além do desconto:
${template.benefits.map(b => `- ${b}`).join('\n')}

Sugestões: ${recommendations.join(', ')}

Esperamos te ver em breve!
Equipe GetNexo`;

return {
  emailHtml,
  emailText,
  couponUrl,
  template
};
